import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol} from './index.js';
import type {
  IncomingMessage,
  ListSessionsMessage,
  OutgoingMessage,
  SessionListMessage,
  SessionSummaryFrame,
} from './index.js';
import * as subprotocol from './transport/ws/subprotocol.js';

describe('the package root', () => {
  it('exports the hal.v1 marker with the reader a WsAuthenticator uses', () => {
    expect({marker: HAL_WS_SUBPROTOCOL, reader: credentialFromSubprotocol}).toEqual({
      marker: subprotocol.HAL_WS_SUBPROTOCOL,
      reader: subprotocol.credentialFromSubprotocol,
    });
  });

  it('exports ListSessionsMessage, SessionSummaryFrame and SessionListMessage in the incoming and outgoing unions', () => {
    const request: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
    };
    const row: SessionSummaryFrame = {
      sessionId: 's2',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-01T00:02:00.000Z',
      entryCount: 4,
    };
    const response: SessionListMessage = {type: 'session_list', sessions: [row]};
    const incoming: IncomingMessage = request;
    const outgoing: OutgoingMessage = response;

    expect({incoming, outgoing}).toEqual({
      incoming: request,
      outgoing: response,
    });
  });
});

