import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitCheck = parseLimit(message.limit);
  if (!limitCheck.valid) return limitCheck;

  const beforeCheck = parseBefore(message.before);
  if (!beforeCheck.valid) return beforeCheck;

  const listFrame: ListSessionsMessage = {type: 'list_sessions'};
  if (limitCheck.limit !== undefined) listFrame.limit = limitCheck.limit;
  if (beforeCheck.before !== undefined) listFrame.before = beforeCheck.before;

  return {valid: true, data: listFrame};
}

function parseLimit(rawLimit: unknown): {valid: true; limit: number | undefined} | ValidationFailure {
  if (rawLimit === undefined) return {valid: true, limit: undefined};
  if (typeof rawLimit !== 'number' || !Number.isInteger(rawLimit) || rawLimit < 0) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  return {valid: true, limit: rawLimit};
}

function parseBefore(rawBefore: unknown): {valid: true; before: SessionCursor | undefined} | ValidationFailure {
  if (rawBefore === undefined) return {valid: true, before: undefined};
  if (typeof rawBefore !== 'object' || rawBefore === null || Array.isArray(rawBefore)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }

  const candidate = rawBefore as Record<string, unknown>;
  const sessionId = candidate.sessionId;
  if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_SESSION_ID_LENGTH) {
    return {valid: false, error: `list_sessions before.sessionId must be a 1-${MAX_SESSION_ID_LENGTH} character string`};
  }

  const updatedAt = candidate.updatedAt;
  if (!isFiniteTimestamp(updatedAt)) {
    return {valid: false, error: 'list_sessions before.updatedAt must be a valid date string or finite timestamp'};
  }

  return {valid: true, before: {sessionId, updatedAt}};
}

function isFiniteTimestamp(rawTimestamp: unknown): rawTimestamp is string | number {
  if (typeof rawTimestamp !== 'string' && typeof rawTimestamp !== 'number') return false;
  return Number.isFinite(new Date(rawTimestamp).getTime());
}

